import { NavContextMenuPatchCallback } from "@api/ContextMenu";
import { Settings } from "@api/Settings";
import { getUserSettingLazy } from "@api/UserSettings";
import { DeleteIcon, SafetyIcon } from "@components/Icons";
import definePlugin from "@utils/types";
import { Message, User } from "@vencord/discord-types";
import { ChannelStore, Menu, UserGuildSettingsStore, UserStore } from "@webpack/common";

const StatusSettings = getUserSettingLazy<string>("status", "status")!;
const PLUGIN_ID = "DND-Whitelist";

interface IMessageCreate {
    type: "MESSAGE_CREATE";
    optimistic: boolean;
    isPushNotification: boolean;
    channelId: string;
    message: Message;
}
interface ICallCreate {
    type: "CALL_CREATE";
    channelId: string;
}
interface ICallDelete {
    type: "CALL_DELETE";
    channelId: string;
}

function getCurrentUserId(): string | null {
     const userId = UserStore.getCurrentUser()?.id;
    if (!userId)
        throw new Error("UserStore is not ready yet");
    return userId;
}

function getWhitelist(): string[] {
    const userId = getCurrentUserId();
    return Settings.plugins[PLUGIN_ID]?.whitelists?.[userId] ?? [];
}

function saveWhitelist(list: string[]) {
    const userId = getCurrentUserId();
    Settings.plugins[PLUGIN_ID] = Settings.plugins[PLUGIN_ID] ?? {};
    Settings.plugins[PLUGIN_ID].whitelists = Settings.plugins[PLUGIN_ID].whitelists ?? {};
    Settings.plugins[PLUGIN_ID].whitelists[userId] = list;
}

const userContextPatch: NavContextMenuPatchCallback = (children, { user }: { user?: User, onClose(): void; }) => {
    if (!user) return;
    const currentUser = UserStore.getCurrentUser();

    if (!currentUser)
        return;

    if (user.id === currentUser.id)
        return;
    const isWhitelisted: boolean = getWhitelist().includes(user.id);
    children.push(
        <Menu.MenuItem
            label={isWhitelisted ? "Remove from DND whitelist" : "Add to DND whitelist"}
            id="vc-dnd-whitelist-user"
            icon={isWhitelisted ? DeleteIcon : SafetyIcon}
            action={() => {
                if (isWhitelisted) {
                    const updatedList = getWhitelist().filter(id => id !== user.id);
                    saveWhitelist(updatedList);
                    console.log(`[${PLUGIN_ID}] Removed user ${user.username}(${user.id}) from DND whitelist`);
                }
                else {
                    const updatedList = getWhitelist();
                    updatedList.push(user.id);
                    saveWhitelist(updatedList);
                    console.log(`[${PLUGIN_ID}] Added user ${user.username}(${user.id}) to DND whitelist`);
                }
            }}
        />
    );
};

function _isLocalDnd(): boolean {
    const status = StatusSettings.getSetting();
    return status === "dnd";
}
function isMuted(channelId: string) {
    const channel = ChannelStore.getChannel(channelId);

    if (!channel?.guild_id)
        return false;

    return UserGuildSettingsStore.isChannelMuted(
        channel.guild_id,
        channelId
    );
}
function getDmUserIds(channelId: string): string[] {
    const channel = ChannelStore.getChannel(channelId);

    if (!channel)
        return [];

    return channel.recipients ?? [];
}


const MessageURL = "";
const messageAudio = new Audio(`data:audio/mpeg;base64,${MessageURL}`);
messageAudio.volume = 0.5;
messageAudio.preload = "auto";
function notif() {
    messageAudio.currentTime = 0;
    messageAudio.play().catch(console.error);
}
const CallURL = ""
const callAudio = new Audio(`data:audio/mpeg;base64,${CallURL}`);
callAudio.loop = true;
callAudio.volume = 0.5;
callAudio.preload = "auto";

export function startCallSound() {
    callAudio.currentTime = 0;

    callAudio.play().catch(console.error);
}

export function stopCallSound() {
    callAudio.pause();
    callAudio.currentTime = 0;
}
export default definePlugin({
    name: "DND-Whitelist",
    description: "creates a whitelist for notifications while in dnd mode",
    authors: [{ name: "bluocaroot", id: 478551117903691777n }],
    contextMenus: {
        "user-context": userContextPatch,
        "user-profile-actions": userContextPatch,
        "user-profile-overflow-menu": userContextPatch,
    },
    flux: {
        async MESSAGE_CREATE({ optimistic, type, message, channelId }: IMessageCreate) {
            if (optimistic || type !== "MESSAGE_CREATE") return;
            const { id } = message.author;
            if (isMuted(channelId))
            {
                console.log("Channel is muted");
                return;
            }
            console.log(`Received message from user ID: ${id}`);
            if (!_isLocalDnd()) return;
            console.log("User is in DND mode");
            const whitelist: string[] = getWhitelist();
            if (whitelist.includes(id)) {
            console.log("Playing notification for whitelisted user");
            notif();
            }
        },
        async CALL_CREATE({ type,channelId }: ICallCreate) {
            console.log("CALL_CREATE event received");
            if (type !== "CALL_CREATE")
                return;

            if (!_isLocalDnd() || isMuted(channelId))
                return;

            const whitelist: string[] = getWhitelist();

            const recipients = getDmUserIds(channelId);

            const isWhitelisted = recipients.some(id =>
                whitelist.includes(id)
            );

            if (isWhitelisted) {
                console.log("Incoming call from whitelisted user");
                startCallSound();
            }
        },
        async CALL_DELETE({ type, channelId }: ICallDelete){
            console.log("CALL_DELETE event received");

            if (type !== "CALL_DELETE")
                return;

            if (!_isLocalDnd() || isMuted(channelId))
                return;

            const whitelist: string[] = getWhitelist();

            const recipients = getDmUserIds(channelId);

            const isWhitelisted = recipients.some(id =>
                whitelist.includes(id)
            );

            if (isWhitelisted) {
                stopCallSound();
            }
        }
    }
});
